const res = $input.first().json;

if (!res || !Array.isArray(res.data)) {
  throw new Error('Guard: unexpected n8n API response. Check API key / URL.');
}

const me = Number($execution.id);
const older = res.data.filter(e => Number(e.id) < me);

if (older.length > 0) {
  return [];
}

return [{ json: { go: true } }];

const answerBank = {
  _note: "PROVISIONAL TEST ANSWER BANK — These answers are for workflow testing only and have NOT been approved by 2-SMT. Replace or confirm them with the client's official answers before production. Null answers deliberately require MANUAL_REVIEW.",
  facts: [
    {
      id: "contact-mailbox",
      category: "general",
      keywords: ["contact", "reach you", "email address", "who do i email"],
      answer: "Thank you for contacting us. I can help direct your inquiry, but I don't have a verified support email address to share. Our team will confirm the correct contact details."
    },
    {
      id: "response-sla",
      category: "general",
      keywords: ["how fast", "response time", "when will you reply", "how long"],
      answer: "Thank you for reaching out. I don't have a verified response-time commitment to share. Our team will confirm the expected response time."
    },
    {
      id: "services-offered",
      category: "sales",
      keywords: ["what do you offer", "services", "training", "consultation", "1-hour session", "book a session"],
      answer: "Thank you for your interest. I don't have a verified list of current services or training options, so I don't want to provide inaccurate information. Our team can confirm the available options and next steps."
    },
    {
      id: "scheduling-link",
      category: "sales",
      keywords: ["schedule", "book a call", "calendly", "booking link"],
      answer: null
    },
    {
      id: "handoff-5w-pattern",
      category: "support",
      keywords: ["handoff", "hand off", "pass down", "shift change", "shift handover", "what should i write", "documentation"],
      answer: "A useful shift-handover note can include: what happened, where it happened, when it happened, what actions were taken, and what needs follow-up. Include only verified observations and follow your organization's documentation and handover procedures."
    },
    {
      id: "swaptronics-definition",
      category: "support",
      keywords: ["swaptronics", "known good board", "board swap"],
      answer: "I don't have a verified, organization-specific definition or approved procedure for Swaptronics. Please confirm the intended meaning and any applicable procedure with your technical team before taking action."
    },
    {
      id: "safety-escalation-boundary",
      category: "troubleshooting",
      keywords: ["machine down", "line down", "line stop", "urgent", "won't cycle", "wont cycle", "yield issue", "asap", "tool fault"],
      answer: "This issue may require prompt attention from the responsible operations or technical team. Follow your site's safety and escalation procedures. Do not bypass safety devices or attempt an unfamiliar repair. If there is an immediate safety risk, follow the site's emergency procedures."
    },
    {
      id: "haptic-supervisor-curriculum-exists",
      category: "sales",
      keywords: ["haptic supervisor", "curriculum", "webinar training", "workbook"],
      answer: "Thank you for your interest. I don't have verified information confirming the availability or contents of the Haptic Supervisor curriculum, webinars, or workbook. Our team will need to confirm these details."
    },
    {
      id: "pricing",
      category: "sales",
      keywords: ["price", "cost", "how much", "pricing", "rate", "quote"],
      answer: null
    },
    {
      id: "product-availability",
      category: "sales",
      keywords: ["available", "when can i get", "release date", "launch date"],
      answer: null
    },
    {
      id: "delivery-format",
      category: "sales",
      keywords: ["delivery", "how is it delivered", "in person", "remote", "online"],
      answer: null
    }
  ]
};

return $input.all().map(item => ({
  json: {
    ...item.json,
    answerBank
  }
}));

const raw = $json.output ?? $json.text ?? $json.response ?? '';

const email = $('Loop Over Items').item.json;
const answerBank =
  $('Load Answer Bank').item.json.answerBank ?? null;

function cleanHtml(value) {
  return String(value ?? '')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function normalize(value) {
  return String(value ?? '')
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const subject = email.subject || email.Subject || '';
const emailBody =
  email.textPlain ||
  email.text ||
  cleanHtml(email.html || email.textHtml || '') ||
  email.snippet ||
  '';

const emailText = normalize(`${subject} ${emailBody}`);

let parsed;

try {
  const cleaned = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  parsed = JSON.parse(cleaned);

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('Invalid classifier object');
  }
} catch {
  parsed = {
    decision: 'MANUAL_REVIEW',
    category: 'classification_error',
    priority: 'high',
    reason: 'Classifier output was invalid and requires human review.'
  };
}

const allowed = ['IGNORE', 'MANUAL_REVIEW', 'REPLY'];

let decision = String(parsed.decision || '').toUpperCase();
let category = parsed.category || 'uncategorized';
let priority = ['low', 'medium', 'high'].includes(
  String(parsed.priority || '').toLowerCase()
)
  ? String(parsed.priority).toLowerCase()
  : 'high';

let reason = parsed.reason || 'Classification reason is missing.';

if (!allowed.includes(decision)) {
  decision = 'MANUAL_REVIEW';
  category = 'classification_error';
  priority = 'high';
  reason = 'Classifier returned an invalid decision.';
}

const sensitivePatterns = [
  /\brefunds?\b/i,
  /\bpayments?\b/i,
  /\bcredit cards?\b/i,
  /\bdebit cards?\b/i,
  /\bcard details?\b/i,
  /\bpasswords?\b/i,
  /\bcredentials?\b/i
];

const urgentPatterns = [
  /\bmachine down\b/i,
  /\bline down\b/i,
  /\bline stop\b/i,
  /\bwon't cycle\b/i,
  /\bwont cycle\b/i,
  /\btool fault\b/i,
  /\byield issue\b/i,
  /\basap\b/i
];

if (sensitivePatterns.some(p => p.test(emailText))) {
  decision = 'MANUAL_REVIEW';
  category = 'sensitive_request';
  priority = 'high';
  reason = 'Sensitive payment or credential-related content requires human review.';
} else if (urgentPatterns.some(p => p.test(emailText))) {
  decision = 'MANUAL_REVIEW';
  category = 'urgent_operational_issue';
  priority = 'high';
  reason = 'Urgent operational issue requires human review.';
}

const facts = Array.isArray(answerBank?.facts)
  ? answerBank.facts
  : [];

const matchedAnswerFacts = facts.filter(fact => {
  if (!fact || !Array.isArray(fact.keywords)) return false;

  return fact.keywords.some(keyword => {
    const term = normalize(keyword);
    return term.length > 0 && (` ${emailText} `).includes(` ${term} `);
  });
});

function isApprovedAnswer(fact) {
  if (typeof fact?.answer !== 'string') return false;

  const answer = fact.answer.trim();

  return answer.length > 0 &&
    !/placeholder|supplied by 2-smt/i.test(answer);
}

if (decision === 'REPLY') {
  if (!Array.isArray(answerBank?.facts)) {
    decision = 'MANUAL_REVIEW';
    category = 'answer_bank_unavailable';
    priority = 'high';
    reason = 'Answer Bank is missing or invalid.';
  } else if (matchedAnswerFacts.length === 0) {
    decision = 'MANUAL_REVIEW';
    category = 'unsupported_request';
    priority = 'high';
    reason = 'No matching Answer Bank entry was found.';
  } else if (!matchedAnswerFacts.every(isApprovedAnswer)) {
    decision = 'MANUAL_REVIEW';
    category = 'answer_not_approved';
    priority = 'high';
    reason = 'A matching Answer Bank entry has no approved usable answer.';
  }
}

return [{
  json: {
    decision,
    category,
    priority,
    reason,
    classifierRaw: raw,
    messageId: email.id || email.messageId || email.message_id || '',
    threadId: email.threadId || email.thread_id || '',
    from: email.from || email.From || '',
    to: email.to || email.To || '',
    subject,
    emailBody,
    answerBank,
    matchedAnswerFacts: matchedAnswerFacts.map(fact => ({
      id: fact.id,
      category: fact.category,
      answer: fact.answer
    }))
  }
}];

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const c = $('Parse Classification').item.json;
const reason = $('Prepare Manual Review Log').item.json.Reason ?? c.reason;

const text = [
  '⚠️ <b>MANUAL REVIEW REQUIRED</b>',
  '',
  `<b>From:</b> ${esc(c.from)}`,
  `<b>Subject:</b> ${esc(c.subject || 'No Subject')}`,
  `<b>Category:</b> ${esc(c.category)}`,
  `<b>Priority:</b> ${esc(c.priority)}`,
  '',
  '<b>Reason:</b>',
  esc(String(reason ?? '').slice(0, 3000))
].join('\n');

return { json: { ...$json, telegram_text: text } };

const esc = s => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const cls = $('Parse Classification').item.json;

const body = String($json.reply_body ?? $json.output ?? '')
  .replace(/\\n/g, '\n')   // literal "\n" strings from the LLM -> real newlines
  .replace(/\*\*/g, '')    // strip markdown bold
  .trim();

const MAX = 3000; // Telegram hard limit is 4096 chars
const clipped = body.length > MAX ? body.slice(0, MAX) + '…' : body;

const text = [
  '<b>NEW SUPPORT REPLY FOR APPROVAL</b>',
  '',
  `<b>From:</b> ${esc(cls.from)}`,
  `<b>Subject:</b> ${esc(cls.subject)}`,
  `<b>Category:</b> ${esc(cls.category)}`,
  '',
  '<b>Proposed reply:</b>',
  `<pre>${esc(clipped)}</pre>`
].join('\n');

return { json: { ...$json, telegram_text: text } };
